from fractions import Fraction


def best_average(a: list[int], k: int) -> list[int]:
    n = len(a)
    prefix = [0] * (n + 1)
    for i, value in enumerate(a):
        prefix[i + 1] = prefix[i] + value

    # Maintain candidate starting prefix indices with a convex hull.
    hull = []
    head = 0
    best_num, best_den = 0, 1

    def cross(i: int, j: int, m: int) -> int:
        return (prefix[j] - prefix[i]) * (m - j) - (prefix[m] - prefix[j]) * (j - i)

    for end in range(k, n + 1):
        start = end - k

        while len(hull) - head >= 2 and cross(hull[-2], hull[-1], start) <= 0:
            hull.pop()

        hull.append(start)

        while len(hull) - head >= 2:
            i, j = hull[head], hull[head + 1]
            if (prefix[end] - prefix[i]) * (end - j) <= (prefix[end] - prefix[j]) * (end - i):
                head += 1
            else:
                break

        i = hull[head]
        num = prefix[end] - prefix[i]
        den = end - i
        if num * best_den > best_num * den:
            best_num, best_den = num, den

        if head > 0 and head * 2 > len(hull):
            hull = hull[head:]
            head = 0

    fraction = Fraction(best_num, best_den)
    return [fraction.numerator, fraction.denominator]
